// Regenerates src/lib/lang/dicier-codes.ts from the vendored Dicier codes list.
// Parse rules per docs/DESIGN.md §4.1: skip ':'-suffixed category headers, blank
// lines, and literal 'etc.' lines; deduplicate across sections; keep codes that
// contain spaces. The list is known non-exhaustive (see DESIGN.md §9) — unknown
// codes are a warning (W004), not an error.
//
// Generated file format (two exports, one source of truth for both):
// - DICIER_CODES: ReadonlySet<string> — every unique code, sorted. This is what
//   the checker (W004) and evaluator (D005) consume; its contents are unchanged
//   by the category work below.
// - DICIER_CODE_CATEGORIES: ReadonlyMap<string, string> — code → the header of
//   the section where the code FIRST appears (matching the dedupe rule), in the
//   same sorted order. The vendored list groups codes under lowercase category
//   headers ("card suits:"); ALL-CAPS headers ("FRANÇAIS:") are language markers,
//   so codes unique to a non-English section get "<category> — <LANGUAGE>".
//   Consumed by editor autocomplete as detail text (DESIGN.md §6.3).
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const source = join(root, "docs/vendor/dicier-v1.5.4/Dicier codes v1_5_4.txt");
const target = join(root, "src/lib/lang/dicier-codes.ts");

const codes = new Set();
const categories = new Map(); // code → category label of first occurrence
let language = null; // null while inside the leading (English) section
let category = "uncategorized";
for (const raw of readFileSync(source, "utf8").split(/\r?\n/)) {
  const line = raw.trim();
  if (!line) continue;
  if (line.endsWith(":")) {
    const name = line.slice(0, -1).trim();
    // A header whose letters are all uppercase is a language marker, not a
    // category ("FRANÇAIS", "KNIŽEVNI HRVATSKI"); categories are prose-cased.
    if (name === name.toUpperCase() && name !== name.toLowerCase()) {
      language = name;
    } else {
      category = name;
    }
    continue;
  }
  if (/^etc\.?$/i.test(line)) continue; // explicit non-exhaustiveness marker
  codes.add(line);
  if (!categories.has(line)) {
    categories.set(line, language === null ? category : `${category} — ${language}`);
  }
}

if (categories.size !== codes.size) {
  throw new Error(`category map (${categories.size}) out of sync with codes (${codes.size})`);
}
const sorted = [...codes].sort();
const codesBody = sorted.map((c) => `  ${JSON.stringify(c)},`).join("\n");
const categoriesBody = sorted
  .map((c) => `  [${JSON.stringify(c)}, ${JSON.stringify(categories.get(c))}],`)
  .join("\n");
mkdirSync(dirname(target), { recursive: true });
writeFileSync(
  target,
  `// Generated by scripts/generate-dicier-codes.mjs — do not edit by hand.
// ${sorted.length} unique codes from Dicier v1.5.4 (list is non-exhaustive; see docs/DESIGN.md §9).
export const DICIER_CODES: ReadonlySet<string> = new Set([
${codesBody}
]);

/** code → source-list section header of its first occurrence (autocomplete
 * detail text, DESIGN.md §6.3). Same key set as DICIER_CODES. */
export const DICIER_CODE_CATEGORIES: ReadonlyMap<string, string> = new Map([
${categoriesBody}
]);
`,
);
console.log(`Wrote ${sorted.length} codes (with categories) to ${target}`);
